<script lang="ts">
  import {onMount,onDestroy} from 'svelte';
  export let csrf:string;
  export let apiPrefix='';
  type Settings=Record<string,number|boolean|string|null>;
  type Report={organisation_id:string|null;project_id:string|null;official_cost_monitoring_configured:boolean;billing_settings_url:string;usage_url:string;balance_status:string;funding_separation:string;cost_warning:string;usage_markup_percent:string|null;health:{status:string;error_code:string;observed:number|null};settings:Settings;cost_observations:{start_utc:number;amount_decimal:string;currency:string;project_id:string;observed:number}[];spend_limit_observations:{scope:string;available:boolean;threshold_cents_usd?:number;enforcement?:string;observed:number}[];recharge_break_even:Record<string,string|number|boolean|null|string[]>;operations:Record<string,unknown>};
  let data:Report|null=null,busy=false,error='',message='',disposed=false;
  let values:Record<string,string>={},reviewed=false;
  let controller:AbortController|undefined;
  const fields:Record<string,string>={reserve_target_pence:'Provider reserve target (GBP pence)',owner_reported_reserve_pence:'Owner-reported provider reserve equivalent (GBP pence; unverified)',stripe_percent_bps:'Stripe processing percentage (basis points)',stripe_fixed_pence:'Stripe fixed processing fee (GBP pence)',climate_bps:'Stripe Climate contribution (basis points)',fx_cost_bps:'Additional FX cost estimate (basis points)',refund_dispute_risk_bps:'Refund/dispute risk allowance (basis points)',infrastructure_bps:'Infrastructure allowance (basis points)',target_margin_bps:'Required margin (basis points)'};
  const metrics:Record<string,string>={usage_deductions_gbp:'Customer AI usage deducted (GBP)',provider_cost_usd:'Metered customer provider cost (USD)',provider_cost_gbp_at_usage_fx:'Provider cost at usage FX (GBP)',prepaid_liability_gbp:'Outstanding prepaid balances (GBP)',reserved_usage_gbp:'In-flight usage held (GBP)',customer_debt_gbp:'Customer balance deficits held for review (GBP)',gross_payments_pence:'Gross AI funding receipts (pence)',refunded_pence:'Refunded AI funding (pence)',observed_stripe_fees_pence:'Verified processing fees, complete coverage (pence)',partial_observed_stripe_fees_pence:'Observed processing fees, partial coverage (pence)',climate_expenditure_pence:'Actual Climate expenditure (pence)',actual_fx_fees_pence:'Actual FX fees (pence)',net_accounting_profit_gbp:'Verified net accounting profit (GBP)',available_stripe_cash_pence:'Available Stripe cash (pence)',pending_topups:'Pending automatic purchases',failed_topups:'Payments needing attention',unknown_usage:'Unconfirmed usage records'};
  async function load(path='',body?:Record<string,unknown>){
    if(disposed||busy)return;
    busy=true;error='';message='';controller=new AbortController();const active=controller;
    const timeout=setTimeout(()=>active.abort(),45000);
    try{
      const response=await fetch(apiPrefix+'/billing/ai-budget/provider-funding'+path,{credentials:'same-origin',signal:active.signal,...(body?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)}:{})});
      const value=await response.json();
      if(!response.ok)throw new Error('request_failed');
      if(disposed)return;
      if(path){message='Saved. Refresh to review the latest observations.';}
      else{data=value;values=Object.fromEntries(Object.keys(fields).map(key=>[key,value.settings[key]===null?'':String(value.settings[key])]));reviewed=value.settings.financial_review_completed===true;}
    }catch{if(!disposed)error='This funding request could not be confirmed. Refresh or check configuration; no funding purchase was made.';}
    finally{clearTimeout(timeout);if(!disposed)busy=false;}
  }
  function save(){const settings:Record<string,number|boolean|null>={financial_review_completed:reviewed};for(const key of Object.keys(fields))settings[key]=values[key]===''?null:Number(values[key]);void load('/settings',settings);}
  const date=(ts:number)=>new Date(ts*1000).toISOString().slice(0,10);
  const display=(value:unknown)=>value===null||value===undefined?'Unavailable / not verified':String(value);
  onMount(()=>{void load();});onDestroy(()=>{disposed=true;controller?.abort();});
</script>

<section class="funding" aria-label="AI Provider Funding" aria-busy={busy}>
  <header><div><p class="eyebrow">Platform owner only</p><h2>AI Provider Funding</h2><p>Customer balances, Stripe receipts and OpenAI funding are separate.</p></div><button disabled={busy} on:click={()=>load()}>Refresh observations</button></header>
  {#if error}<p role="alert" class="notice">{error}</p>{/if}{#if message}<p role="status" class="notice">{message}</p>{/if}
  {#if data}
    <article><h3>Provider status</h3><p><strong>{data.health.status.replaceAll('_',' ')}</strong>{#if data.health.error_code} · {data.health.error_code}{/if}</p><p>{data.balance_status}</p><p>Organisation: <bdi>{data.organisation_id||'Not configured'}</bdi> · Project: <bdi>{data.project_id||'Not configured'}</bdi></p><p>{data.funding_separation}</p><p><a href={data.billing_settings_url} target="_blank" rel="noopener noreferrer">Open official OpenAI billing settings ↗</a> · <a href={data.usage_url} target="_blank" rel="noopener noreferrer">Open official usage dashboard ↗</a></p></article>
    <article><h3>Manual OpenAI setup</h3><ol><li>In the correct API organisation, add the platform's payment method and initial API funding.</li><li>Configure OpenAI's own auto recharge, its threshold, amount and monthly limit.</li><li>Review organisation and project usage limits and payment failure notifications.</li><li>Keep a provider reserve to cover Stripe payout delays. Verify funding directly in OpenAI; a V7 customer purchase does not fund it.</li></ol><p>Official cost monitoring: {data.official_cost_monitoring_configured?'configured':'unavailable — requires a separately authorised OpenAI admin key in server secrets'}. No API key or payment details are displayed here.</p><button disabled={busy||!data.official_cost_monitoring_configured} on:click={()=>load('/sync',{days:7})}>Read official seven-day costs and spend limits</button><p>{data.cost_warning}</p></article>
    <article><h3>Funding warnings and financial coverage</h3><p>{display(data.operations.scope)}</p>{#each (data.operations.warnings as string[]||[]) as warning}<p class="notice">{warning.replaceAll('_',' ')}</p>{/each}<dl>{#each Object.entries(metrics) as [key,label]}<div><dt>{label}</dt><dd><bdi>{display(data.operations[key])}</bdi></dd></div>{/each}</dl><p>{display(data.operations.limits)}</p></article>
    <article><h3>Reserve and cost assumptions</h3><p>Blank means unknown. Enter verified fee terms or explicitly approved estimates; 100 basis points is 1%. Saving these inputs does not change customer usage prices or activate live recharges.</p><form on:submit|preventDefault={save}><div class="fields">{#each Object.entries(fields) as [key,label]}<label>{label}<input type="number" min="0" max={key.endsWith('pence')?100000000:10000} step="1" value={values[key]} on:input={(event)=>values={...values,[key]:event.currentTarget.value}}/></label>{/each}</div><label class="checkbox"><input type="checkbox" bind:checked={reviewed}/>I have reviewed these financial assumptions. Live-payment activation and any pricing change still require a separate deployment approval.</label><button disabled={busy}>Save financial assumptions</button></form></article>
    <article><h3>£5 automatic purchase break-even</h3><p>Current configured usage markup: {data.usage_markup_percent===null?'Unavailable':data.usage_markup_percent+'%'}. This page cannot change it.</p><dl>{#each Object.entries(data.recharge_break_even) as [key,value]}<div><dt>{key.replaceAll('_',' ')}</dt><dd>{Array.isArray(value)?value.join(', '):display(value)}</dd></div>{/each}</dl></article>
    <article><h3>Official spend-limit observations</h3>{#each data.spend_limit_observations as row}<p>{row.scope}: {row.available?'USD '+((row.threshold_cents_usd||0)/100).toFixed(2)+' per month; '+row.enforcement:'Unavailable'} · observed {date(row.observed)} UTC</p>{:else}<p>Not read yet. No zero or unlimited spending limit is inferred.</p>{/each}</article>
    <article><h3>Provider cost trend</h3><p>Delayed official costs in USD. These are expenditure observations, not an available balance or proof that auto recharge succeeded.</p><div class="scroll"><table><thead><tr><th>Date (UTC)</th><th>Project</th><th>USD cost</th><th>Observed (UTC)</th></tr></thead><tbody>{#each data.cost_observations as row}<tr><td>{date(row.start_utc)}</td><td><bdi>{row.project_id||'Unassigned'}</bdi></td><td>{row.amount_decimal}</td><td>{date(row.observed)}</td></tr>{:else}<tr><td colspan="4">No verified cost observations yet.</td></tr>{/each}</tbody></table></div></article>
  {/if}
</section>
<style>
  .funding{display:grid;gap:18px;color:#173c30}header{display:flex;align-items:start;justify-content:space-between;gap:18px}h2,h3,p{margin:0 0 12px}p,li{line-height:1.6}.eyebrow{font-size:12px;text-transform:uppercase}article{background:#fff;border:1px solid #d7dfda;border-radius:14px;padding:24px;min-width:0}.notice{padding:14px;background:#f1f4f2;border-inline-start:4px solid #315b47}button{padding:12px 18px;min-height:44px;background:#174c38;color:white;border:0;border-radius:8px;font:inherit;cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}a{color:#14543a;text-decoration:underline}dl{margin:0}dl>div{display:grid;grid-template-columns:1fr 1fr;gap:16px;border-bottom:1px solid #e2e7e4;padding:12px 0}dd{margin:0;overflow-wrap:anywhere}.fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}label{display:grid;gap:7px;font-weight:600}input[type=number]{padding:12px;min-height:44px;border:1px solid #aebfb4;border-radius:7px;font:inherit;width:100%;box-sizing:border-box}.checkbox{display:flex;align-items:start;margin:20px 0;line-height:1.6}.checkbox input{width:22px;height:22px;flex:none;margin:3px 8px 0 0}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;text-align:start}td,th{padding:12px;border-bottom:1px solid #ddd}:focus-visible{outline:3px solid #60ab88;outline-offset:3px}@media(max-width:650px){header{display:block}.fields,dl>div{grid-template-columns:1fr}article{padding:18px}}
</style>
